fun findCycle(): List<Long>? {
    val g = waitsFor()
    val done = HashSet<Long>()
    val path = ArrayList<Long>()
    fun visit(t: Long): List<Long>? {
        path += t
        for (next in g[t].orEmpty().sorted()) {
            val at = path.indexOf(next)
            if (at >= 0) return path.subList(at, path.size).toList()
            if (next !in done) visit(next)?.let { return it }
        }
        path.removeAt(path.size - 1)
        done += t                     // no cycle goes through t
        return null
    }
    for (t in g.keys.sorted()) if (t !in done) visit(t)?.let { return it }
    return null
}

fun detectDeadlocks(): List<Long> {
    val victims = mutableListOf<Long>()
    while (true) {
        val cycle = findCycle() ?: return victims
        val victim = cycle.max()      // the youngest: started last, least work lost
        abort(victim)                 // releases its locks and drops its waiting request
        victims += victim
    }
}

// Aborting removes the victim's node: its locks are released (no edges into it) and its
// waiting request is dropped (no edge out of it), so the cycle loses a link.
